package io.github.jesterportfolio.hearth.verification;

import io.github.jesterportfolio.hearth.features.*;
import io.github.jesterportfolio.hearth.inventory.*;
import io.github.jesterportfolio.hearth.persistence.*;
import io.github.jesterportfolio.hearth.combat.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import org.bukkit.*;
import org.bukkit.inventory.*;
import org.bukkit.entity.Villager;
import net.kyori.adventure.text.Component;

/** 새 격리 DB/실제 Paper 객체만 사용합니다. Player 조작 성공을 주장하지 않습니다. */
final class FeaturesVerification {
    private final PostgresProgressStore db;private final S4Features features;private final PaperInventoryCodec codec;private final Executor owner;private final BiConsumer<Boolean,String> check;private final IntFunction<ServerProgressAccess.Context> context;private final Supplier<World> world;
    FeaturesVerification(PostgresProgressStore db,S4Features features,PaperInventoryCodec codec,Executor owner,BiConsumer<Boolean,String> check,IntFunction<ServerProgressAccess.Context> context,Supplier<World> world){this.db=db;this.features=features;this.codec=codec;this.owner=owner;this.check=check;this.context=context;this.world=world;}
    private <T> CompletionStage<T> main(CompletionStage<T> work){return work.thenApplyAsync(Function.identity(),owner);}
    private CompletionStage<Void> rejected(Supplier<? extends CompletionStage<?>> work){try{return main(work.get().handle((v,e)->{if(e==null)throw new IllegalStateException("EXPECTED_REJECTION");return (Void)null;}));}catch(IllegalStateException expected){if(expected.getMessage().equals("EXPECTED_REJECTION"))throw expected;return CompletableFuture.completedFuture(null);}}
    private InventoryPayload payload(Material type,int count,String name){var slots=new ItemStack[41];slots[0]=new ItemStack(type,count);slots[0].editMeta(m->m.displayName(Component.text(name)));return codec.encode(slots);}
    private CompletionStage<Void> fixture(int n){var c=context.apply(n);return main(db.createPlayer(c,"s4-private-probe")).thenCompose(v->main(db.createInventory(c,payload(Material.DIAMOND,3,"원본 보존")))).thenApply(v->null);}
    private SceneContent.Scene scene(){return features.sceneContent.scenes().get("public_arrival");}
    CompletionStage<Void> prepare(ServerProgressAccess.Context first,Object token,ServerProgressAccess.Context second,Object token2){
        return completeScene(first,token,true).thenCompose(v->completeScene(second,token2,false))
            .thenCompose(v->fixture(120)).thenCompose(v->fixture(121)).thenCompose(v->fixture(122)).thenCompose(v->fixture(123)).thenCompose(v->fixture(124)).thenCompose(v->fixture(125))
            .thenCompose(v->storage()).thenCompose(v->device()).thenCompose(v->sceneConflict()).thenCompose(v->recovery()).thenRun(this::paperObjects);
    }
    private CompletionStage<Void> completeScene(ServerProgressAccess.Context c,Object token,boolean skip){
        var progress=features.scenes.progress;
        return progress.open(c,token,scene(),()->true).thenCompose(s->{check.accept(!s.state().completed(),"s4_scene_first_mandatory_"+c.playerId());return rejected(()->progress.start(s,UUID.randomUUID(),Cutscene.Choice.SKIP)).thenCompose(v->progress.start(s,UUID.randomUUID(),Cutscene.Choice.WATCH)).thenCompose(v->progress.advance(s,s.state().request(),0)).thenCompose(v->{var restarted=new SceneProgress(features.store,owner,()->{});return restarted.open(c,new Object(),scene(),()->true).thenAccept(read->check.accept(!read.state().completed()&&read.state().frame()==1,"s4_scene_interrupted_persisted_still_mandatory"));}).thenCompose(v->progress.advance(s,s.state().request(),1)).thenCompose(v->progress.advance(s,s.state().request(),2)).thenCompose(v->{check.accept(s.state().completed()&&Cutscene.choiceRequired(s.state()),"s4_scene_confirmed_last_frame_and_choice");if(!skip)return CompletableFuture.completedFuture(s.state());return progress.start(s,UUID.randomUUID(),Cutscene.Choice.WATCH).thenCompose(x->{check.accept(Cutscene.choiceRequired(s.state()),"s4_scene_second_watch_keeps_next_choice");return progress.start(s,UUID.randomUUID(),Cutscene.Choice.SKIP);});}).thenCompose(v->main(features.store.read(c,"cutscene",scene().id()))).thenCompose(before->{var old=s.state();return progress.start(s,UUID.randomUUID(),Cutscene.Choice.REPLAY).thenCompose(v->main(features.store.read(c,"cutscene",scene().id()))).thenAccept(after->check.accept(before.equals(after)||before.orElseThrow().revision()==after.orElseThrow().revision()&&Arrays.equals(before.orElseThrow().payload(),after.orElseThrow().payload())&&old.equals(s.state()),"s4_scene_readonly_replay_keeps_revision_and_state"));});});
    }
    private CompletionStage<Void> storage(){
        var c=context.apply(120);var probe=new PersonalStorage(db,features.store,owner,()->{},codec::equivalent);int[] dirty={0};
        return probe.open(c,new Object(),()->true,()->dirty[0]++).thenCompose(account->{var ender=payload(Material.EMERALD,7,"개인 27칸");probe.observe(account,ender);check.accept(dirty[0]==1,"s4_ender_observe_marks_existing_inventory_dirty");return main(probe.saveInventory(c,0,payload(Material.DIAMOND,4,"최신 원본"))).thenCompose(saved->{check.accept(saved.revision()==1&&account.revision()==0,"s4_ender_and_41_slots_confirmed_atomically");var first=features.store.inventory(c,1,saved.payload(),0,ender).handle((v,e)->e==null);var second=features.store.inventory(c,1,saved.payload(),0,ender).handle((v,e)->e==null);return main(first.thenCombine(second,(a,b)->a!=b));}).thenCompose(won->{check.accept(won,"s4_ender_real_PG_concurrent_CAS_one_winner");return main(db.readInventory(c));}).thenCompose(before->main(features.store.read(c,"ender","inventory")).thenCompose(enderBefore->rejected(()->features.store.inventory(c,before.revision(),payload(Material.GOLD_INGOT,9,"거부될 값"),-1,PersonalStorage.empty())).thenCompose(v->main(db.readInventory(c))).thenCompose(after->{check.accept(before.equals(after),"s4_ender_conflict_rolls_back_41_slots");return main(features.store.read(c,"ender","inventory"));}).thenAccept(after->check.accept(enderBefore.orElseThrow().revision()==after.orElseThrow().revision()&&Arrays.equals(enderBefore.orElseThrow().payload(),after.orElseThrow().payload()),"s4_ender_conflict_preserves_27_slot_original"))))
            .thenCompose(v->rejected(()->probe.saveInventory(c,2,payload(Material.DIAMOND,5,"거부될 값")))).thenRun(()->check.accept(account.held()&&account.revision()==0,"s4_ender_stale_account_HOLD_no_retry"));});
    }
    private CompletionStage<Void> device(){
        var c=context.apply(121);
        return main(db.readInventory(c)).thenCompose(before->{var next=features.device.plan(c,before.payload());check.accept(codec.equivalent(features.device.plan(c,next),next),"s4_phone_plan_idempotent_and_original_metadata_kept");var items=codec.decode(next);check.accept(Arrays.stream(items).filter(i->features.device.owned(i,c)).count()==1&&!features.device.owned(items[1],context.apply(120)),"s4_phone_one_owner_run_bound_item");return main(features.store.device(c,0,next,-1)).thenCompose(saved->rejected(()->features.store.device(c,1,payload(Material.COAL,9,"거부될 값"),-1)).thenCompose(v->main(db.readInventory(c))).thenAccept(after->check.accept(after.equals(saved.inventory()),"s4_phone_duplicate_issuance_rolls_back_inventory")));}).thenCompose(v->main(db.readInventory(c))).thenCompose(before->main(db.saveInventory(c,before.revision(),payload(Material.DIAMOND,3,"원본 보존")))).thenCompose(lost->{check.accept(!DeviceRules.issue(true,false)&&DeviceRules.issue(true,true),"s4_phone_saved_issue_flag_requires_explicit_replacement");return main(features.store.device(c,lost.revision(),features.device.plan(c,lost.payload()),0));}).thenAccept(reissued->check.accept(reissued.inventory().revision()==3&&reissued.feature().revision()==1,"s4_phone_explicit_single_reissue_atomic"));
    }
    private CompletionStage<Void> sceneConflict(){var c=context.apply(125);var probe=new SceneProgress(features.store,owner,()->{});return probe.open(c,new Object(),scene(),()->true).thenCompose(s->main(features.store.write(c,"cutscene",scene().id(),-1,SceneProgress.encode(scene(),Cutscene.State.empty()))).thenCompose(winner->rejected(()->probe.start(s,UUID.randomUUID(),Cutscene.Choice.WATCH))).thenCompose(v->main(features.store.read(c,"cutscene",scene().id()))).thenAccept(row->check.accept(s.held()&&s.state().attempts()==0&&SceneProgress.decode(scene(),row.orElseThrow().payload()).attempts()==0,"s4_scene_real_PG_CAS_HOLD_original_preserved")));}
    private CompletionStage<Void> recovery(){var exit=new CombatContent.Exit(new FieldContent.Point(2.5,64,1.5),0,0,.5,List.of(new CombatContent.Effect("REGENERATION",0,40)));CompletionStage<Void> work=CompletableFuture.completedFuture(null);for(int n=122;n<=124;n++){final int id=n;work=work.thenCompose(v->{var c=context.apply(id);var attempt=new UUID(500,id);return main(features.recovery.start(c,attempt,null,world.get().getUID(),exit,"SURVIVAL")).thenCompose(active->id==123?CompletableFuture.completedFuture(active):main(features.recovery.end(c,attempt))).thenCompose(state->id==124?main(features.recovery.claim(c,attempt,new UUID(501,id))):CompletableFuture.completedFuture(state)).thenAccept(state->check.accept(RecoveryLedger.restart(state)==(id==122?RecoveryLedger.Action.RETURN:RecoveryLedger.Action.HOLD),"s4_recovery_confirmed_boundary_"+state.phase()));});}return work;}
    private void paperObjects(){
        World w=world.get();var holder=Bukkit.createInventory(null,27,Component.text("개인 엔더 보관함"));holder.setItem(26,new ItemStack(Material.IRON_INGOT,5));var slots=Arrays.copyOf(holder.getContents(),41);check.accept(codec.decode(PersonalStorage.validate(codec.encode(slots)))[26].getAmount()==5,"s4_native_27_slots_metadata_serialization");
        var map=Bukkit.createMap(w);map.setLocked(true);map.setTrackingPosition(false);for(var r:List.copyOf(map.getRenderers()))map.removeRenderer(r);check.accept(map.isLocked()&&!map.isTrackingPosition()&&map.getRenderers().isEmpty(),"s4_native_map_locked_no_shared_vanilla_terrain");
        var rows=HudMinimap.frame(new byte[16384],List.of(),0,true,i->0);check.accept(MiniMapOverlay.title(rows,96)!=null,"s4_native_minimap_glyph_Component_without_Player_claim");
        for(Material type:List.of(Material.FURNACE,Material.HOPPER,Material.BLUE_SHULKER_BOX,Material.BREWING_STAND)){int x=20+type.ordinal()%8;int z=20+type.ordinal()/8%8;var block=w.getBlockAt(x,64,z);if(!block.isEmpty())throw new IllegalStateException("FIXTURE_NOT_AIR");block.setType(type);var inv=((InventoryHolder)block.getState()).getInventory();inv.setItem(0,new ItemStack(type==Material.BREWING_STAND?Material.GLASS_BOTTLE:Material.COAL,1));check.accept(inv.getItem(0)!=null,"s4_native_container_"+type);}
        var target=w.spawn(new Location(w,5,65,5),Villager.class,e->{e.setAI(false);e.setPersistent(false);});try{var origin=new CombatContent.Pose(w.getUID(),4,65,5,0,0);var slow=new CombatContent.Pattern("slow","둔화",1,1000,100,6,2,CombatContent.Shape.SPHERE,0,0,6,CombatContent.Origin.LOCKED,CombatContent.Technique.SLOW,0,60,2,300);PaperCombatTrials.applyEffects(slow,target,origin);check.accept(target.hasPotionEffect(org.bukkit.potion.PotionEffectType.SLOWNESS),"s4_native_entity_slow_effect");var repel=new CombatContent.Pattern("repel","밀어내기",1,1000,100,6,2,CombatContent.Shape.SPHERE,0,0,6,CombatContent.Origin.LOCKED,CombatContent.Technique.REPEL,.4,0,1,0);PaperCombatTrials.applyEffects(repel,target,origin);check.accept(target.getVelocity().getX()>.3&&target.getVelocity().getY()>=.19,"s4_native_entity_repel_effect");}finally{target.remove();}
    }
    CompletionStage<Void> restored(ServerProgressAccess.Context first,ServerProgressAccess.Context second){
        CompletionStage<Void> work=CompletableFuture.completedFuture(null);for(var c:List.of(first,second))work=work.thenCompose(v->main(features.store.read(c,"cutscene",scene().id())).thenAccept(row->{var state=SceneProgress.decode(scene(),row.orElseThrow().payload());check.accept(state.completed()&&state.skipFuture()==c.equals(first)&&state.attempts()==(c.equals(first)?3:1),"s4_new_JVM_scene_personal_complete_choice_restored");}));
        return work.thenCompose(v->main(db.readInventory(context.apply(120)))).thenAccept(row->check.accept(row.revision()==2&&codec.decode(row.payload())[0].getAmount()==4,"s4_new_JVM_41_slots_original_after_rollback"))
            .thenCompose(v->main(features.store.read(context.apply(120),"ender","inventory"))).thenAccept(row->check.accept(row.orElseThrow().revision()==1&&codec.decode(InventoryPayload.parse(row.orElseThrow().payload()))[0].getAmount()==7,"s4_new_JVM_personal_27_slots_restored"))
            .thenCompose(v->main(db.readInventory(context.apply(121)))).thenAccept(row->check.accept(row.revision()==3&&Arrays.stream(codec.decode(row.payload())).filter(i->features.device.owned(i,context.apply(121))).count()==1,"s4_new_JVM_single_bound_phone_restored"))
            .thenCompose(v->main(features.recovery.read(context.apply(122)))).thenCompose(row->{var state=row.orElseThrow();check.accept(RecoveryLedger.restart(state)==RecoveryLedger.Action.RETURN,"s4_new_JVM_pending_return_resumable");var request=UUID.randomUUID();return main(features.recovery.claim(context.apply(122),state.attempt(),request)).thenCompose(claimed->rejected(()->features.recovery.done(context.apply(122),state.attempt(),UUID.randomUUID()))).thenCompose(v->main(features.recovery.read(context.apply(122)))).thenCompose(claimed->{check.accept(RecoveryLedger.restart(claimed.orElseThrow())==RecoveryLedger.Action.HOLD,"s4_new_JVM_claimed_unknown_movement_HOLD");return main(features.recovery.done(context.apply(122),state.attempt(),request));}).thenAccept(done->check.accept(RecoveryLedger.restart(done)==RecoveryLedger.Action.NONE,"s4_new_JVM_confirmed_done_no_second_return"));})
            .thenCompose(v->main(features.recovery.read(context.apply(123)))).thenAccept(row->check.accept(RecoveryLedger.restart(row.orElseThrow())==RecoveryLedger.Action.HOLD,"s4_new_JVM_active_battle_HOLD_no_respawn"))
            .thenCompose(v->main(features.recovery.read(context.apply(124)))).thenAccept(row->check.accept(RecoveryLedger.restart(row.orElseThrow())==RecoveryLedger.Action.HOLD,"s4_new_JVM_unknown_movement_HOLD_no_teleport"))
            .thenRun(()->{World w=world.get();for(Material type:List.of(Material.FURNACE,Material.HOPPER,Material.BLUE_SHULKER_BOX,Material.BREWING_STAND)){var b=w.getBlockAt(20+type.ordinal()%8,64,20+type.ordinal()/8%8);check.accept(b.getType()==type&&((InventoryHolder)b.getState()).getInventory().getItem(0)!=null,"s4_new_JVM_world_container_preserved_"+type);}});
    }
}
